-- Additional Owner sample products. Run this COMPLETE file in Supabase SQL Editor.
-- Preserves existing products, store settings, Owner identity and all access policies.
begin;

do $import$
declare
 owner_profile public.lk_profiles;
 item jsonb;
 product_key text;
 stamp text:=to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
begin
 perform pg_advisory_xact_lock(730412);
 select p.* into owner_profile from public.lk_profiles p
 join lk_private.owner_account o on o.auth_id=p.auth_id
 where p.role='customer' and p.username='scorpion' and p.verification_status='approved';
 if not found then raise exception 'Activate the protected Scorpion Owner account first.'; end if;

 insert into public.lk_shops(id,owner_id,profile) values(owner_profile.id,owner_profile.auth_id,
  jsonb_build_object('id',owner_profile.id,'name','Scorpion Tech - Owner Store',
  'tagline','A selection of sample tech products.',
  'description','Sample listings curated for the LK Tech Store preview. Photos are illustrative; prices and stock are demonstration values.',
  'email','','phone','','location','','color','#c5a6f5'))
 on conflict (id) do nothing;
 if not exists(select 1 from public.lk_shops where id=owner_profile.id and owner_id=owner_profile.auth_id) then
  raise exception 'Owner storefront identity mismatch; nothing has been imported.';
 end if;

 for item in select value from jsonb_array_elements($catalog$[{"id":"product_ab11b359f3a058a785f751decc3e1dab","name":"Everyday Creator Laptop (Sample)","summary":"Sample listing: a silver laptop for your work and creative setup.","description":"A sample laptop listing for exploring the tech collection. The photo is illustrative; the name, price, and stock are demonstration values, not an offer for the pictured brand or model. Hardware specifications are not asserted.\n\nPhoto: Chris Ried / Unsplash.","category":"Tech","price":699.99,"priceCents":69999,"stock":8,"status":"active","sku":"OWNER-SAMPLE-LAPTOP","image":"data:image/jpeg;base64,","color":"#d5dfeb","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v2","imageCredit":"Chris Ried","imageSource":"https://unsplash.com/photos/silver-laptop-computer-on-white-surface-LfG7RwMM6g8"},{"id":"product_bd6d6f46ae86518c94ad9be0d96a9490","name":"Everyday Smartwatch (Sample)","summary":"Sample listing: a clean watch design with a light-colored band.","description":"A sample smartwatch listing for browsing wearable accessories. The photo is illustrative; the name, price, and stock are demonstration values, not an offer for the pictured brand or model. Compatibility and health-tracking features are not asserted.\n\nPhoto: Jozsef Hocza / Unsplash.","category":"Accessories","price":89.99,"priceCents":8999,"stock":20,"status":"active","sku":"OWNER-SAMPLE-SMARTWATCH","image":"data:image/jpeg;base64,","color":"#d7e2da","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v2","imageCredit":"Jozsef Hocza","imageSource":"https://unsplash.com/photos/white-and-black-digital-watch-h1MnFsRI-_I"},{"id":"product_20b610ff3aa95c5897104d882357bd0d","name":"Creator Digital Camera (Sample)","summary":"Sample listing: a classic black camera for a creative collection.","description":"A sample digital camera listing with an illustrative product photograph. The name, price, and stock are demonstration values, not an offer for the pictured brand or model. Sensor, lens, and recording specifications are not asserted.\n\nPhoto: Fujiphilm / Unsplash.","category":"Tech","price":449.99,"priceCents":44999,"stock":6,"status":"active","sku":"OWNER-SAMPLE-CAMERA","image":"data:image/jpeg;base64,","color":"#ded8e9","isNew":true,"isCustom":true,"isSample":true,"sampleCollection":"owner-tech-v2","imageCredit":"Fujiphilm","imageSource":"https://unsplash.com/photos/a-camera-in-the-dark-on-a-black-background-GEWP1mOeXvo"}]$catalog$::jsonb) loop
  product_key:=item->>'id';
  if exists(select 1 from public.lk_products where id=product_key and
    (owner_id<>owner_profile.auth_id or seller_id<>owner_profile.id or data->>'sku' is distinct from item->>'sku')) then
   raise exception 'Sample product identity conflict; nothing has been imported.';
  end if;
  -- Same-owner SKU matches and previously imported IDs are preserved on reruns.
  if not exists(select 1 from public.lk_products where id=product_key or
    (seller_id=owner_profile.id and lower(data->>'sku')=lower(item->>'sku'))) then
   insert into public.lk_products(id,seller_id,owner_id,data)
   values(product_key,owner_profile.id,owner_profile.auth_id,
    item||jsonb_build_object('sellerId',owner_profile.id,'image',lk_private.image(item->'image'),
    'createdAt',stamp,'updatedAt',stamp));
  end if;
 end loop;
end $import$;
commit;

select p.data->>'name' as product,p.data->>'price' as price_usd,p.status
from public.lk_products p join lk_private.owner_account o on o.auth_id=p.owner_id
where p.data->>'sampleCollection'='owner-tech-v2' order by p.data->>'name';
